package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Node_absUrl_TriageGen0Test {

    private Node node;

    @Before
    public void setUp() {
        // Initialize the base URI
        String baseUri = "http://example.com/path/";
        node = new Element("div", "", baseUri).wrap(new Document(baseUri));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAbsUrl_withEmptyAttributeKey_throwsException() {
        node.absUrl("");
    }

    @Test
    public void testAbsUrl_withNonExistentAttribute_returnsEmpty() {
        assertEquals("", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_withRelativeUrl() {
        node.attr("src", "/image.jpg");
        assertEquals("http://example.com/image.jpg", node.absUrl("src"));
    }

    @Test
    public void testAbsUrl_withAbsoluteUrlInsideAttribute() {
        node.attr("href", "http://external.com/page");
        assertEquals("http://external.com/page", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_withMalformedBaseUri_returnsEmpty() {
        node.setBaseUri("ht://malformed");
        node.attr("src", "/image.jpg");
        assertEquals("", node.absUrl("src"));
    }

    @Test
    public void testAbsUrl_withMalformedRelativeUrl_returnsEmpty() {
        node.attr("src", "ht://malformed/image.jpg");
        assertEquals("", node.absUrl("src"));
    }

    @Test
    public void testAbsUrl_withProtocolRelativeUrl() {
        node.attr("src", "//external.com/image.jpg");
        assertEquals("http://external.com/image.jpg", node.absUrl("src"));
    }

    @Test
    public void testAbsUrl_withComplexRelativeUrl() {
        node.attr("href", "/path/file?query=123");
        assertEquals("http://example.com/path/file?query=123", node.absUrl("href"));
    }

    @Test
    public void testAbsUrl_withProtocolRelativeAndComplexRelativeUrl() {
        node.attr("href", "//example.com/path/file?query=123");
        assertEquals("http://example.com/path/file?query=123", node.absUrl("href"));
    }
}
